/** Reproduce the normative integer CORDIC constants without host floating point. */
import { readFile, writeFile } from 'node:fs/promises'

const precision = 10n ** 100n
const iterations = 48
function atanInverse(divisor: bigint) {
  let power = divisor, sum = 0n
  for (let term = 0n;; term++) {
    const value = precision / (power * (2n * term + 1n))
    if (value === 0n) return sum
    sum += term % 2n === 0n ? value : -value
    power *= divisor * divisor
  }
}
function roundedRatio(numerator: bigint, denominator: bigint) {
  const whole = numerator / denominator, remainder = numerator % denominator
  return whole + (2n * remainder > denominator
    || (2n * remainder === denominator && whole % 2n !== 0n) ? 1n : 0n)
}
function sqrt(value: bigint) {
  let current = 1n << ((BigInt(value.toString(2).length) + 1n) / 2n)
  for (;;) {
    const next = (current + value / current) / 2n
    if (next >= current) return current
    current = next
  }
}
const pi = 16n * atanInverse(5n) - 4n * atanInverse(239n)
const scale = 1n << 62n
const angles = Array.from({ length: iterations }, (_, index) => index === 0
  ? scale / 8n : roundedRatio(atanInverse(1n << BigInt(index)) * scale, 2n * pi))
let numerator = 1n, denominator = 1n
for (let index = 0; index < iterations; index++) {
  const square = 1n << BigInt(2 * index)
  numerator *= square; denominator *= square + 1n
}
const squared = numerator * scale * scale
const floor = sqrt(squared / denominator)
const comparison = 4n * squared - (2n * floor + 1n) ** 2n * denominator
const gain = floor + (comparison > 0n || (comparison === 0n && floor % 2n !== 0n) ? 1n : 0n)
const generated = `// Generated by specs/tools/uv-trig-constants.ts --write; do not edit.
pub const GAIN: i128 = ${gain};
pub const ANGLES: [i128; ${iterations}] = [
${angles.map(angle => `    ${angle},`).join('\n')}
];
`
const destination = new URL('../../runtime/kernel/src/trig_constants.rs', import.meta.url)
if (process.argv.includes('--write')) await writeFile(destination, generated)
else {
  if (await readFile(destination, 'utf8') !== generated)
    throw new Error('fixed trigonometry constants differ from the normative integer generator')
  console.log(`Verified ${iterations} Q62 CORDIC angles and reciprocal gain.`)
}
